typedef unsigned char MENU_UINT8;

struct MenuColor
{
	MENU_UINT8 r,g,b,a;
};

enum MenuEntryFlags
{
	MENTRY_VISIBLE = 1 << 0,
	MENTRY_ENABLED = 1 << 1,
	MENTRY_ACTIVE = 1 << 2,
};

extern MenuColor entryactive;
extern MenuColor entryenabled;
extern MenuColor entrydisabled;

class MenuEntry
{
	unsigned int flags;

protected:
	bool GetFlag( unsigned int flag ) { return (flags & flag)!=0; }

public:
	bool IsVisible( void ) { return GetFlag(MENTRY_VISIBLE); }
	bool IsEnabled( void ) { return IsVisible() && GetFlag(MENTRY_ENABLED); }
	bool IsActive( void ) { return GetFlag(MENTRY_ACTIVE); }
	MenuColor GetColor( void );
};

MenuColor MenuEntry::GetColor( void )
{
	if ( IsActive() )
	{
		return entryactive;
	}
	else if ( IsEnabled() )
	{
		return entryenabled;
	}
	else
	{
		return entrydisabled;
	}
}
